3	namespace App\Models\Billing;
4	
5	use App\Models\BaseModel;
6	use App\Models\Core\Professional\Professional;
7	use Illuminate\Database\Eloquent\Relations\BelongsTo;
8	
9	// V2: Stripe-backed subscription linking a professional to a plan. Tracks billing period, cancellation state, and raw provider payload.
10	class Subscription extends BaseModel
11	{
12	    protected $table = 'billing.subscriptions';
13	
14	    public $incrementing = false;
15	
16	    protected $keyType = 'string';
17	
18	    public const STATUS_ACTIVE = 'active';
19	
20	    public const STATUS_PAST_DUE = 'past_due';
21	
22	    public const STATUS_UNPAID = 'unpaid';
23	
24	    public const STATUS_CANCELED = 'canceled';
25	
26	    public const STATUS_INCOMPLETE = 'incomplete';
27	
28	    public const STATUS_INCOMPLETE_EXPIRED = 'incomplete_expired';
29	
30	    public const GRACE_STATUSES = [self::STATUS_ACTIVE, self::STATUS_PAST_DUE];
31	
32	    protected $fillable = [
33	        'id',
34	        'professional_id',
35	        'plan_id',
36	        'provider',
37	        'stripe_customer_id',
38	        'stripe_subscription_id',
39	        'status',
40	        'current_period_start',
41	        'current_period_end',
42	        'cancel_at_period_end',
43	        'trial_ends_at',
44	        'ended_at',
45	        'provider_payload',
46	    ];
47	
48	    protected $hidden = [
49	        'stripe_customer_id',
50	        'stripe_subscription_id',
51	        'provider_payload',
52	    ];
53	
54	    protected $casts = [
55	        'current_period_start' => 'datetime',
56	        'current_period_end' => 'datetime',
57	        'trial_ends_at' => 'datetime',
58	        'ended_at' => 'datetime',
59	        'cancel_at_period_end' => 'boolean',
60	        'provider_payload' => 'array',
61	    ];
62	
63	    public function plan(): BelongsTo
64	    {
65	        return $this->belongsTo(Plan::class, 'plan_id');
66	    }
67	
68	    public function professional(): BelongsTo
69	    {
70	        return $this->belongsTo(Professional::class, 'professional_id');
71	    }
72	
73	    public function isActive(): bool
74	    {
75	        return $this->status === self::STATUS_ACTIVE && $this->ended_at === null;
76	    }
77	
78	    public function isInGracePeriod(): bool
79	    {
80	        return in_array($this->status, self::GRACE_STATUSES, true) && $this->ended_at === null;
81	    }
82	
83	    public function isStripeManaged(): bool
84	    {
85	        return $this->provider === 'stripe';
86	    }
87	
88	    public function isFreeInternal(): bool
89	    {
90	        return $this->provider === 'internal';
91	    }
92	}
