3	namespace App\Models\Core\Gdpr;
4	
5	use App\Models\BaseModel;
6	use App\Models\Core\Professional\Professional;
7	use App\Models\Core\Staff\SidestStaff;
8	use Illuminate\Database\Eloquent\Concerns\HasUuids;
9	use Illuminate\Database\Eloquent\Relations\BelongsTo;
10	
11	// V2: Audit row for professional data exports (self-service + staff-triggered).
12	// Snapshot columns survive the professional's hard-delete (FK SET NULL).
13	class DataExportAudit extends BaseModel
14	{
15	    use HasUuids;
16	
17	    public const TRIGGERED_BY_SELF = 'self';
18	
19	    public const TRIGGERED_BY_STAFF = 'staff';
20	
21	    public const SEND_TO_PROFESSIONAL = 'professional';
22	
23	    public const SEND_TO_STAFF = 'staff';
24	
25	    public const STATUS_QUEUED = 'queued';
26	
27	    public const STATUS_PROCESSING = 'processing';
28	
29	    public const STATUS_COMPLETED = 'completed';
30	
31	    public const STATUS_FAILED = 'failed';
32	
33	    protected $table = 'core.data_export_audit';
34	
35	    public $incrementing = false;
36	
37	    protected $keyType = 'string';
38	
39	    public $timestamps = false; // only created_at + completed_at; no updated_at
40	
41	    protected $fillable = [
42	        'professional_id',
43	        'professional_handle_snapshot',
44	        'professional_email_snapshot',
45	        'triggered_by',
46	        'triggered_by_staff_id',
47	        'recipient_email',
48	        'send_to',
49	        'status',
50	        'file_path',
51	        'file_size_bytes',
52	        'file_sha256',
53	        'record_counts',
54	        'error_message',
55	        'created_at',
56	        'completed_at',
57	    ];
58	
59	    protected $casts = [
60	        'record_counts' => 'array',
61	        'file_size_bytes' => 'integer',
62	        'created_at' => 'datetime',
63	        'completed_at' => 'datetime',
64	    ];
65	
66	    // PII fields — never expose in API responses or job payloads
67	    protected $hidden = [
68	        'professional_email_snapshot',
69	        'recipient_email',
70	        'file_sha256',
71	    ];
72	
73	    protected static function booted(): void
74	    {
75	        static::creating(function (self $audit) {
76	            if (! $audit->status) {
77	                $audit->status = self::STATUS_QUEUED;
78	            }
79	            if (! $audit->created_at) {
80	                $audit->created_at = now();
81	            }
82	        });
83	    }
84	
85	    public function professional(): BelongsTo
86	    {
87	        return $this->belongsTo(Professional::class);
88	    }
89	
90	    public function triggeringStaff(): BelongsTo
91	    {
92	        return $this->belongsTo(SidestStaff::class, 'triggered_by_staff_id');
93	    }
94	
95	    public function markProcessing(): void
96	    {
97	        $this->update(['status' => self::STATUS_PROCESSING]);
98	    }
99	
100	    public function markCompleted(
101	        string $filePath,
102	        int $fileSizeBytes,
103	        string $fileSha256,
104	        array $recordCounts,
105	    ): void {
106	        $this->update([
107	            'status' => self::STATUS_COMPLETED,
108	            'file_path' => $filePath,
109	            'file_size_bytes' => $fileSizeBytes,
110	            'file_sha256' => $fileSha256,
111	            'record_counts' => $recordCounts,
112	            'completed_at' => now(),
113	        ]);
114	    }
115	
116	    public function markFailed(string $error): void
117	    {
118	        $this->update([
119	            'status' => self::STATUS_FAILED,
120	            'error_message' => mb_substr($error, 0, 2000),
121	            'completed_at' => now(),
122	        ]);
123	    }
124	}
